# Fix brief — wt UX polish (shared by all fix agents)

Repo: github.com/mvwi/wt (Go). You are working in an isolated git worktree of it, branched from `fix/ux-polish`.
Read CLAUDE.md first: conventions (cmdContext, internal/git for git, internal/github + IsAvailable(), ui.* output,
ui.Confirm, ui.PrintCTA, commandIcons in root.go for new commands).

Background: a round of hands-on user testing. Raw tester notes (evidence, repro commands):
/private/tmp/claude-501/-Users-michaelwilliams-Dev-wt/10a8e376-1259-4304-8272-99cc91e0bb9b/scratchpad/findings/
(tester-core.md, tester-juggle.md; onboarding + github findings are quoted in your task.)
Sandbox repos for manual checks (local bare remotes, safe to mutate): .../scratchpad/labs/lab1..lab3, and
labs/lab4/bubbletea (real public GitHub clone — READ-ONLY toward GitHub: no push, no PR/issue writes).
Build your own binary (`go build -o /tmp/... ./cmd/wt` → use the scratchpad instead of /tmp) to check behaviour by hand.

Rules
- Fix the root cause once, in shared code. Smallest complete change; no speculative options/abstractions.
- Stay inside the files your task owns where you can; other agents edit other files in parallel. If you must touch a
  file outside your list, keep the hunk small and say so in your report.
- Do NOT edit README.md or CLAUDE.md. Instead, end your report with a "Docs" section listing exact user-facing
  changes (new flags, config keys, behaviour) so the lead can update docs once.
- Add or update a focused test for each non-trivial fix (table tests in the existing *_test.go style).
- Before finishing: `go build ./... && go vet ./... && go test ./...` and `golangci-lint run` (if installed) must pass.
- Writing: comments and messages follow Orwell's rules — short plain words, active voice, no filler.
- Commit your work in your worktree with conventional commits (one per logical fix is ideal). NO attribution lines,
  no "Co-authored-by", no mention of AI. Do not push.
- Report (≤ 30 lines): per item — fixed / partly / skipped (+ why), files touched, how you verified; then Docs.
package cmd

import (
	"fmt"

	"github.com/spf13/cobra"
)

var shellCmd = &cobra.Command{
	Use:   "init-shell <shell>",
	Short: "Print shell integration wrapper",
	Long: `Print a shell wrapper function that enables 'cd' integration.

Add to your shell config:
  Fish:  wt init-shell fish | source
  Bash:  eval "$(wt init-shell bash)"
  Zsh:   eval "$(wt init-shell zsh)"

The wrapper passes a temp file path via WT_CD_FILE. Commands that
need to change directory write the target path to that file, and
the wrapper reads it after the command exits.`,
	Args:      cobra.ExactArgs(1),
	ValidArgs: []string{"fish", "bash", "zsh"},
	RunE:      runShell,
}

func init() {
	rootCmd.AddCommand(shellCmd)
}

func runShell(cmd *cobra.Command, args []string) error {
	switch args[0] {
	case "fish":
		fmt.Print(fishWrapper)
	case "bash":
		fmt.Print(bashWrapper)
	case "zsh":
		fmt.Print(zshWrapper)
	default:
		return fmt.Errorf("unsupported shell: %s (use fish, bash, or zsh)", args[0])
	}
	return nil
}

const fishWrapper = `# wt shell integration (fish)
# Add to ~/.config/fish/config.fish:
#   wt init-shell fish | source

function wt --wraps wt --description "Git worktree manager"
    set -l cdfile (mktemp -t wt-cd.XXXXXXXX)
    or begin
        command wt $argv
        return $status
    end
    WT_CD_FILE=$cdfile command wt $argv
    set -l exit_code $status
    if test -s $cdfile
        read -l target < $cdfile
        and cd $target
    end
    rm -f $cdfile
    return $exit_code
end

# Completions are handled by cobra's built-in fish completion.
# Generate with: wt completion fish | source
`

const bashWrapper = `# wt shell integration (bash)
# Add to ~/.bashrc:
#   eval "$(wt init-shell bash)"

wt() {
    local cdfile _wt_prev_trap
    cdfile=$(mktemp -t wt-cd.XXXXXXXX) || {
        command wt "$@"
        return $?
    }
    _wt_prev_trap=$(trap -p EXIT 2>/dev/null)
    trap 'rm -f "$cdfile"' EXIT
    WT_CD_FILE="$cdfile" command wt "$@"
    local exit_code=$?
    if [ -s "$cdfile" ]; then
        cd "$(cat "$cdfile")" || true
    fi
    rm -f "$cdfile"
    if [ -n "$_wt_prev_trap" ]; then
        eval "$_wt_prev_trap"
    else
        trap - EXIT
    fi
    return $exit_code
}

# Generate completions with: eval "$(wt completion bash)"
`

const zshWrapper = `# wt shell integration (zsh)
# Add to ~/.zshrc:
#   eval "$(wt init-shell zsh)"

wt() {
    local cdfile _wt_prev_trap
    cdfile=$(mktemp -t wt-cd.XXXXXXXX) || {
        command wt "$@"
        return $?
    }
    _wt_prev_trap=$(trap -p EXIT 2>/dev/null)
